ST.xhtml:p:
Rtring(CLK := g_bMiddleAvoidAxisM317Enbale);
IF Rtring.Q THEN
  IF M.PARAMETER_P[317] = 1.0 THEN (*检测中卡位置*)
    g_bMiddleAvoidZCannotMoveAlarm := FALSE;
    IF M.PARAMETER_Q[317] = 0.0 THEN(*0:前进检测是否小于设置的坐标值报警*)
      bMiddleAvoidAxisForward := TRUE;
      bMiddleAvoidAxisbackward := FALSE;(*1:后退检测是否大于0报警*)
    ELSIF M.PARAMETER_Q[317] = 1.0 THEN
      bMiddleAvoidAxisForward := FALSE;
      bMiddleAvoidAxisbackward := TRUE;
    END_IF;
    nCheckState := 10;
  ELSIF M.PARAMETER_P[317] = 2.0 THEN(*检测主卡后退位置*)
    nCheckState := 100;
  ELSIF M.PARAMETER_P[317] = 3.0 THEN(*检测主卡绝对运动完成*)
    nCheckState := 20;
  ELSIF M.PARAMETER_P[317] = 4.0 THEN(*检测中卡绝对运动完成*)
    nCheckState := 30;  
  ELSIF M.PARAMETER_P[317] = 10.0 THEN (*检测中卡位置是不是在安全位置或者0位上 不在就报警*)  
    g_bMiddleAvoidZCannotMoveAlarm := FALSE;
    nCheckState := 200;
  END_IF;
  g_bMiddleAvoidAxisM317Enbale := FALSE;
END_IF;

CASE nCheckState OF
  0:
	nCheckState := 0;
  10:
	IF bMiddleAvoidAxisForward THEN
		IF g_dAntiRejection5Coordinate <= dMiddleAvoidAxisPosDetection-0.5 THEN
		  g_bMiddleAvoidZCannotMoveAlarm := TRUE;
		  nCheckState := 0;
		ELSE
		  M.ENABLE[317] := 0;
		  nCheckState := 0;
		END_IF;
    ELSE
		IF g_dAntiRejection5Coordinate >= dMiddleAvoidBackAxisPosDetection THEN
		  g_bMiddleAvoidZCannotMoveAlarm := TRUE;
		  nCheckState := 0;
		ELSE
		  M.ENABLE[317] := 0;
		  nCheckState := 0;
		END_IF;
    END_IF;
  20:
	IF g_bAntiRejection4AbsDone THEN
      M.ENABLE[317] := 0;
      nCheckState := 0;
    END_IF;
  30:
	IF g_bAntiRejection5AbsDone THEN
      M.ENABLE[317] := 0;
      nCheckState := 0;
    END_IF;

  100:
	IF g_dAntiRejection4Coordinate <= dMiddleAvoidAxisBackPosLessThan THEN
		  M.ENABLE[317] := 0;
    END_IF;
  200:
    IF (0.0+dMiddleAvoidAxisSafePosAllowErrorValue >=g_dAntiRejection5Coordinate AND  g_dAntiRejection5Coordinate >= 0.0-dMiddleAvoidAxisSafePosAllowErrorValue) OR 
      (dMiddleAvoidAxisRelSafePos+dMiddleAvoidAxisSafePosAllowErrorValue >=g_dAntiRejection5Coordinate AND g_dAntiRejection5Coordinate >= dMiddleAvoidAxisRelSafePos-dMiddleAvoidAxisSafePosAllowErrorValue) THEN
      g_bMiddleAvoidZCannotMoveAlarm := FALSE;
      nCheckState := 0; 
      M.ENABLE[317] := 0;
    ELSE
      IF g_bIsConfigMiddleAvoidAxis2 AND NOT g_bIsConfigMiddleAvoidAxis1 THEN
        nSaveCheckState:=nCheckState; 
        g_bMiddleAvoidZCannotMoveAlarm := TRUE;
        nCheckState := 0;  
      ELSE
        g_bMiddleAvoidZCannotMoveAlarm := FALSE;
        nCheckState := 0; 
        M.ENABLE[317] := 0;
      END_IF;  
    END_IF;  
END_CASE;

IF g_bPlcStartBuffer THEN
  nCheckState:=nSaveCheckState;
END_IF;
IF g_bPlcPauseBuffer THEN
  nSaveCheckState := nCheckState;

END_IF;
IF g_bPlcResetBuffer THEN
  nCheckState := 0;
  nSaveCheckState:= 0;
  g_bMiddleAvoidAxisM317Enbale := FALSE;
  M.ENABLE[317] := 0;
END_IF;
